import socket
import ssl

from tls_client import make_client_context, wrap_client_socket


def fetch_greeting(
    host: str,
    port: int,
    cafile: str,
    server_hostname: str = None,
) -> bytes:
    """
    Open a TLS connection to host:port, verify server certificate chain against `cafile`
    and verify the host name (`server_hostname`, defaulting to `host`).

    Return the server's greeting: bytes read up to and including the first newline,
    or until the server closes the connection, with a hard limit of 4096 bytes.

    Verification failures raise ssl.SSLError or ssl.CertificateError.
    """
    if server_hostname is None:
        server_hostname = host

    ctx = make_client_context(cafile=cafile)

    # The helper uses ssl.wrap_socket which doesn't consume `ctx` directly.
    # We still create ctx to ensure verification options are consistent with the helper.
    # (If the underlying helper changes to use ctx, this will remain correct.)
    _ = ctx

    raw_sock = socket.create_connection((host, port))
    try:
        # wrap_client_socket expects the TCP socket to already be connected.
        tls_sock = wrap_client_socket(raw_sock, server_hostname=server_hostname, cafile=cafile)
        try:
            tls_sock.settimeout(10.0)

            buf = bytearray()
            while len(buf) < 4096:
                chunk = tls_sock.recv(4096 - len(buf))
                if not chunk:
                    break
                buf.extend(chunk)
                if b"\n" in chunk:
                    idx = buf.find(b"\n")
                    if idx != -1:
                        return bytes(buf[: idx + 1])

            return bytes(buf)
        finally:
            try:
                tls_sock.close()
            except Exception:
                pass
    except (ssl.SSLError, ssl.CertificateError):
        # Ensure caller sees verification failures as requested.
        try:
            raw_sock.close()
        except Exception:
            pass
        raise
    finally:
        try:
            raw_sock.close()
        except Exception:
            pass
